CREATE TYPE "WorkStatus" AS ENUM ('PLANNED','ACTIVE','AT_RISK','BLOCKED','COMPLETED','CANCELLED');
CREATE TYPE "WorkPriority" AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TYPE "EventType" AS ENUM ('RALLY','TOWN_HALL','PRESS_CONFERENCE','COMMUNITY_MEETING','VOLUNTEER_TRAINING','POLICY_FORUM','CANDIDATE_VISIT','INTERNAL_MEETING');
CREATE TYPE "TrainingStatus" AS ENUM ('NOT_STARTED','SCHEDULED','IN_PROGRESS','COMPLETED','EXEMPT');
CREATE TYPE "ParticipationStatus" AS ENUM ('INVITED','REGISTERED','ATTENDED','CANCELLED','NO_SHOW');
ALTER TABLE "campaigns" ADD COLUMN "country" TEXT NOT NULL DEFAULT 'Unspecified', ADD COLUMN "election_type" TEXT NOT NULL DEFAULT 'Unspecified', ADD COLUMN "starts_at" DATE, ADD COLUMN "ends_at" DATE;
ALTER TABLE "campaigns" ADD CONSTRAINT "campaign_dates_valid" CHECK ("ends_at" IS NULL OR "starts_at" IS NULL OR "ends_at" >= "starts_at");

CREATE TABLE "campaign_leaders" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"campaign_id" UUID NOT NULL,"user_id" UUID NOT NULL,"title" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE,FOREIGN KEY("user_id") REFERENCES "auth_users"("id") ON DELETE RESTRICT,UNIQUE("campaign_id","user_id"));
CREATE INDEX "campaign_leaders_tenant_campaign_idx" ON "campaign_leaders"("tenant_id","campaign_id");
CREATE TABLE "initiatives" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"campaign_id" UUID NOT NULL,"owner_id" UUID,"title" TEXT NOT NULL,"description" TEXT,"priority" "WorkPriority" NOT NULL DEFAULT 'NORMAL',"status" "WorkStatus" NOT NULL DEFAULT 'PLANNED',"starts_at" TIMESTAMP(3),"due_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE,FOREIGN KEY("owner_id") REFERENCES "auth_users"("id") ON DELETE SET NULL);
CREATE INDEX "initiatives_tenant_campaign_status_idx" ON "initiatives"("tenant_id","campaign_id","status");
CREATE TABLE "activities" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"campaign_id" UUID NOT NULL,"initiative_id" UUID,"owner_id" UUID,"title" TEXT NOT NULL,"description" TEXT,"priority" "WorkPriority" NOT NULL DEFAULT 'NORMAL',"status" "WorkStatus" NOT NULL DEFAULT 'PLANNED',"starts_at" TIMESTAMP(3),"due_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE,FOREIGN KEY("initiative_id") REFERENCES "initiatives"("id") ON DELETE SET NULL,FOREIGN KEY("owner_id") REFERENCES "auth_users"("id") ON DELETE SET NULL);
CREATE INDEX "activities_tenant_campaign_status_idx" ON "activities"("tenant_id","campaign_id","status");
CREATE TABLE "campaign_tasks" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"campaign_id" UUID NOT NULL,"activity_id" UUID,"owner_id" UUID,"title" TEXT NOT NULL,"description" TEXT,"priority" "WorkPriority" NOT NULL DEFAULT 'NORMAL',"status" "WorkStatus" NOT NULL DEFAULT 'PLANNED',"due_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE,FOREIGN KEY("activity_id") REFERENCES "activities"("id") ON DELETE SET NULL,FOREIGN KEY("owner_id") REFERENCES "auth_users"("id") ON DELETE SET NULL);
CREATE INDEX "campaign_tasks_tenant_campaign_status_due_idx" ON "campaign_tasks"("tenant_id","campaign_id","status","due_at");
CREATE TABLE "task_dependencies" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"task_id" UUID NOT NULL,"depends_on_task_id" UUID NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("task_id") REFERENCES "campaign_tasks"("id") ON DELETE CASCADE,FOREIGN KEY("depends_on_task_id") REFERENCES "campaign_tasks"("id") ON DELETE CASCADE,UNIQUE("task_id","depends_on_task_id"),CHECK("task_id" <> "depends_on_task_id"));
CREATE TABLE "geographic_levels" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"name" TEXT NOT NULL,"order_index" INTEGER NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("tenant_id") REFERENCES "organizations"("id") ON DELETE CASCADE,UNIQUE("tenant_id","order_index"),UNIQUE("tenant_id","name"));
CREATE TABLE "geographic_areas" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"campaign_id" UUID NOT NULL,"level_id" UUID NOT NULL,"parent_id" UUID,"name" TEXT NOT NULL,"code" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE,FOREIGN KEY("level_id") REFERENCES "geographic_levels"("id") ON DELETE RESTRICT,FOREIGN KEY("parent_id") REFERENCES "geographic_areas"("id") ON DELETE RESTRICT);
CREATE INDEX "geographic_areas_tenant_campaign_parent_idx" ON "geographic_areas"("tenant_id","campaign_id","parent_id");
CREATE TABLE "campaign_events" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"campaign_id" UUID NOT NULL,"geographic_area_id" UUID,"type" "EventType" NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"status" "WorkStatus" NOT NULL DEFAULT 'PLANNED',"starts_at" TIMESTAMP(3) NOT NULL,"ends_at" TIMESTAMP(3),"venue" TEXT,"capacity" INTEGER,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE,FOREIGN KEY("geographic_area_id") REFERENCES "geographic_areas"("id") ON DELETE SET NULL,CHECK("ends_at" IS NULL OR "ends_at" >= "starts_at"),CHECK("capacity" IS NULL OR "capacity" >= 0));
CREATE INDEX "campaign_events_tenant_campaign_starts_idx" ON "campaign_events"("tenant_id","campaign_id","starts_at");
CREATE TABLE "volunteers" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"user_id" UUID,"preferred_area_id" UUID,"display_name" TEXT NOT NULL,"contact_authorized" BOOLEAN NOT NULL DEFAULT false,"email" TEXT,"phone" TEXT,"availability" JSONB NOT NULL,"languages" TEXT[] NOT NULL,"skills" TEXT[] NOT NULL,"training_status" "TrainingStatus" NOT NULL DEFAULT 'NOT_STARTED',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("tenant_id") REFERENCES "organizations"("id") ON DELETE CASCADE,FOREIGN KEY("preferred_area_id") REFERENCES "geographic_areas"("id") ON DELETE SET NULL,CHECK("contact_authorized" OR ("email" IS NULL AND "phone" IS NULL)));
CREATE INDEX "volunteers_tenant_training_idx" ON "volunteers"("tenant_id","training_status");
CREATE TABLE "volunteer_assignments" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"campaign_id" UUID NOT NULL,"volunteer_id" UUID NOT NULL,"task_id" UUID,"title" TEXT NOT NULL,"status" "WorkStatus" NOT NULL DEFAULT 'PLANNED',"starts_at" TIMESTAMP(3),"ends_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE,FOREIGN KEY("volunteer_id") REFERENCES "volunteers"("id") ON DELETE CASCADE,FOREIGN KEY("task_id") REFERENCES "campaign_tasks"("id") ON DELETE SET NULL);
CREATE TABLE "event_participation" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"event_id" UUID NOT NULL,"volunteer_id" UUID NOT NULL,"status" "ParticipationStatus" NOT NULL DEFAULT 'INVITED',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("event_id") REFERENCES "campaign_events"("id") ON DELETE CASCADE,FOREIGN KEY("volunteer_id") REFERENCES "volunteers"("id") ON DELETE CASCADE,UNIQUE("event_id","volunteer_id"));
